    "content": "21/08/2026 - 22:00 根据一份日期为 8 月 17 日但尚未公开的决定，荷兰数据保护局（AP）决定对 Uber 处以 8.25 亿欧元罚款，原因是该公司通过自动系统停用司机账户，且未提前通知司机。 路透社查阅的文件显示：“AP 认定 Uber 侵犯了司机的权利，具体而言是侵犯了司机免受具有……重大后果的自动化决策影响的权利。”《通用数据保护条例》（GDPR）禁止做出对个人生活产生重大影响的自动化决策，并要求必须有人工监督以及对此类决策提出异议的途径。 Uber 发言人告诉法新社：“我们强烈反对这一决…"
