    "content": "21/08/2026 - 22:28 周五公布的一项调查显示，欧元区消费者在7月份连续第三个月下调了通胀预期，尽管他们仍预计通胀率将超过欧洲央行（ECB）设定的2%的目标。 总部位于法兰克福的欧洲央行曾在6月份上调利率，并预计下个月将再次加息，以遏制由中东冲突引发的能源驱动型通胀。 欧洲央行调查的中值数据显示，未来12个月的通胀预期为2.9%，低于6月份的3.0%。 三年期通胀预期也有所下调，从6月份的2.8%降至7月份的2.7%；而五年期预期则保持在2.4%不变。 周五发布的一项调查显示，受新订单（尤其是制造业领…"
