    "content": "新华社拉姆安拉8月21日电（记者赵伟宏）据巴勒斯坦通讯社21日报道，巴勒斯坦总统阿巴斯当天发表声明，呼吁以色列政府立即停止并取消“E1区”定居点建设项目招标计划，指出此举直接威胁巴勒斯坦建国进程。 阿巴斯在声明中强调，“E1区”定居点计划将把约旦河西岸切割为南北两部分，同时割裂东耶路撒冷与其周边巴勒斯坦地区的地理联系，严重损害以1967年边界为基础、以东耶路撒冷为首都、拥有主权的独立巴勒斯坦国的建国前景。 阿巴斯指出，该计划公然违反国际法和联合国相关决议，尤其是安理会第2334号决议，是以色列持续推进定居点扩建、实…"
