    "content": "我把相册做成了一个 3D 地球 翻相册的时候突然意识到一件事—— 我拍过的照片分散在五六个地方：手机里、百度网盘、微信朋友圈、QQ 空间、还有几个不知道什么时候注册的图床网站。 更难受的是，那些用来存博客配图的图床，要么是需要进入到二级界面才能放大，要么就是上传限制合规越来越严格。 同时在我前段时间逛 2 站发帖的过程中，因为图片外链接的问题还纠结了一阵子。当时我就想： 能不能有一套自己的外链+相册系统？ 照片全归自己管，谁都删不掉 能当图床用，外链稳定不失效 最好还能在地图上看到自己去过哪儿 于是我花了大概两周的…"
