    "content": "美元指数21日下跌。衡量美元对六种主要货币的美元指数当天下跌0.09%，在汇市尾市收于98.801。截至纽约汇市尾市，1欧元兑换1.1683美元，高于前一交易日的1.1676美元；1英镑兑换1.3652美元，高于前一交易日的1.3628美元。1美元兑换159.02日元，低于前一交易日的159.14日元；1美元兑换0.8008瑞士法郎，高于前一交易日的0.8007瑞士法郎；1美元兑换1.3761加元，低于前一交易日的1.3790加元；1美元兑换9.4626瑞典克朗，低于前一交易日的9.4908瑞典克朗。"
