    "content": "新华社东京8月21日电（记者李诗萌 蓝建中）据日本共同社21日报道，日本政府部门和机构2027财年（2027年4月至2028年3月）预算申请总额预计将超过130万亿日元（1美元约合159日元），相比本财年的122万亿日元显著增加。 其中，日本防卫省计划申请约8.9万亿日元，用于部署拦截型无人机等，申请规模创历史新高。养老金、医疗等社会保障支出预计因人口老龄化增加约3900亿日元。 日本政府各部门和机构需在8月底前提交下一财年的预算申请，为财政部年底前编制预算做准备。此前，日本政府通过设置预算上限控制各部门支出规模，…"
