    "content": "新华社加德满都8月21日电（记者张平）8月18日至21日，全国政协常委、民族和宗教委员会副主任、中国人权研究会常务副会长蒋建国率中国人权研究会代表团赴尼泊尔开展人权交流活动。访问期间，蒋建国出席“看见西藏”故事分享会并致辞，分别会见尼泊尔外交部常秘阿姆里特·巴哈杜尔·拉伊、尼泊尔国家人权委员会主席托普·巴哈杜尔·马加尔等当地人士。 代表团以深入宣介习近平总书记关于尊重和保障人权重要论述，深入宣介习近平总书记心系西藏人民、高度重视西藏发展为切入点，向尼方系统阐释当代中国人权观的深刻内涵，全面介绍中国人权发展道路，生动…"
