    "description": "国际足联纪律委员会21日公布了对2026美加墨世界杯期间阿根廷队多项违规违纪行为的处罚结果：阿根廷足协被罚款32.1万美元（约合人民币216万元），并被限制未来两个主场比赛的观众人数；3名阿根廷队球员和1名教练组成员被处以禁赛和罚款，其中帕雷德斯被禁赛10场。 国际足联表示，阿根廷足协因违反《国际足联纪律准则》中多个条款，被处以总额32.1万美元的罚款。违规包括球迷的歧视性言论和手势、球队不当行为、利用体育赛事进行非体育性质表达等。此外…",
