    "content": "新华社北京8月21日电 记者21日获悉，中央网络安全和信息化委员会近日印发《促进网信企业高质量发展行动计划（2026-2030年）》，提出到2030年，我国网信企业综合实力显著增强，科技创新力、产品硬实力、服务竞争力明显提升，网信产业生态和发展环境全面优化，安全规范、健康有序发展的制度体系更加健全，网信企业赋能经济社会高质量发展的作用更加凸显。 中央网信办有关负责同志介绍，网络信息技术是全球研发投入集中、创新活跃、应用广泛、辐射带动作用显著的技术创新领域。以网络信息技术为核心驱动力、以网络安全和信息化为主要业务的网…"
