    "content": "21/08/2026 - 16:26 伊朗总统马苏德·佩泽希齐扬周五（8月21日）表示，现在是结束与美国战争的时候了。他认为，伊朗目前“处于有利地位”，而美国则希望通过一场新的“经济战争”向伊朗施压。 佩泽希齐扬在与医生代表会面时表示：“现在结束战争更好，因为我们目前处于有利地位，并且能够有尊严地结束战争。”他还说：“全世界都承认我们的胜利，并指出美国违反所有规则，袭击了我们的学校、医院和基础设施。”他补充称，“美国正受到全世界的憎恨。” 据美国媒体报道，美国海军正在组织并保护秘密油轮船队，使其能够通过霍尔木兹海峡…"
