    "content": "21/08/2026 - 16:42 法新社周五(8月21日)的报道称，中国即将发射嫦娥七号（Chang’e-7），这是中国迄今技术最复杂的月球探测任务。该任务的目标是寻找月球南极附近永久处于阴影中的陨石坑内可能存在的冰冻水资源。 这项无人探测任务以中国神话中的月亮女神“嫦娥”命名，将向太阳系最寒冷的区域之一部署一台机器人着陆器、一辆月球车以及一台“跳跃式”探测器。 嫦娥七号将成为中国实现长期目标的重要一步：在月球建立永久性人类存在。目前，中国正推进相关计划，力争在2030年前实现载人登月，并计划到2035年前与俄…"
