    "author": "张玉亮",
    "description": "新华社奥斯陆8月21日电（记者张玉亮）2026年中国国际服务贸易交易会海外分会暨挪威克里斯蒂安松开放日活动21日在挪威西部海滨城市克里斯蒂安松举行。挪威政商界代表在活动上介绍了国家馆建设情况和企业组团参展计划，为挪威以主宾国身份参加今年服贸会预热。 8月21日，在挪威西部城市克里斯蒂安松，克里斯蒂安松市市长内高在2026年中国国际服务贸易交易会海外分会暨挪威克里斯蒂安松开放日活动上致辞。新华社发（董娜摄） 中国驻挪威大使馆经济商务参赞耿…",
    "content": "新华社奥斯陆8月21日电（记者张玉亮）2026年中国国际服务贸易交易会海外分会暨挪威克里斯蒂安松开放日活动21日在挪威西部海滨城市克里斯蒂安松举行。挪威政商界代表在活动上介绍了国家馆建设情况和企业组团参展计划，为挪威以主宾国身份参加今年服贸会预热。 8月21日，在挪威西部城市克里斯蒂安松，克里斯蒂安松市市长内高在2026年中国国际服务贸易交易会海外分会暨挪威克里斯蒂安松开放日活动上致辞。新华社发（董娜摄） 中国驻挪威大使馆经济商务参赞耿洪洲向与会人士介绍说，服贸会是中国扩大高水平开放、促进国际服务贸易合作的重要平台…"
