    "content": "新华社北京8月21日电（记者邹学佳）暑假期间，首都博物馆的中外游客络绎不绝。展台前，孩子们正踮脚观望，目光被4只来自秘鲁的金银羊驼小雕像牢牢吸引。而在不远处，明定陵出土的金翼善冠引得不少观众驻足惊叹。 两批相隔太平洋的“国宝”在京迎来一场难得的“会面”。 近日，在首博举办的“玉米·黄金·美洲豹——玛雅与安第斯古代文明大展”中，来自秘鲁、墨西哥20余家博物馆的约800件美洲古文明文物，与来自明十三陵博物馆的4件宫廷精品文物同馆亮相。 在秘鲁大使馆的鼎力支持下，近期展览再度新增19件秘鲁珍贵文物，其中14件是首次来华。…"
