    "description": "新华社北京8月21日电 德国慕尼黑经济研究所21日表示，德国近四分之一的企业正面临技术工人短缺问题。 慕尼黑经济研究所调查显示，7月有23.2%的受访企业表示缺少具备相应资质的技工，高于4月的21.1%，但低于31.7%的长期平均水平。 这是在德国萨尔州的弗尔克林根钢铁厂遗址拍摄的工业设施（2024年12月18日摄）。新华社记者张帆摄 研究员达里娅·沙勒说，当前德国经济增长乏力，在一定程度上抑制了企业对技工的需求，“随着经济进一步复苏，…",
    "content": "新华社北京8月21日电 德国慕尼黑经济研究所21日表示，德国近四分之一的企业正面临技术工人短缺问题。 慕尼黑经济研究所调查显示，7月有23.2%的受访企业表示缺少具备相应资质的技工，高于4月的21.1%，但低于31.7%的长期平均水平。 这是在德国萨尔州的弗尔克林根钢铁厂遗址拍摄的工业设施（2024年12月18日摄）。新华社记者张帆摄 研究员达里娅·沙勒说，当前德国经济增长乏力，在一定程度上抑制了企业对技工的需求，“随着经济进一步复苏，技工短缺问题或将再度凸显”。 从行业看，电信业技工短缺明显加剧，报告这一问题的企…"
