    "content": "中新网香港8月21日电 非营利国际协作平台“全球新工业革命联盟”(Global New Industrial Revolution Alliance)近日在香港成立，发起人包括来自中国内地和香港，以及美国、欧洲、全球南方国家的知名经济学家、工商实业家、投资人和多边发展机构负责人。"
