    "description": "新华社澳门8月21日电（记者齐菲、宋晨）“浮华清影——清代广东绘画展”21日在澳门艺术博物馆开幕，展出粤港澳三地多家博物馆馆藏清代广东绘画精品。 清代广东绘画是澳门艺术博物馆重要特色馆藏。本次展览以澳门艺术博物馆馆藏为基础，结合广东省博物馆（广州鲁迅纪念馆）、广州艺术博物院（广州美术馆）、香港艺术馆珍藏，共计展出136件（套）书画精品，呈现清代早、中、晚期54位画家在山水、花鸟、人物题材方面的成就，展示清代广东绘画在笔墨技法、题材开拓及…",
    "content": "新华社澳门8月21日电（记者齐菲、宋晨）“浮华清影——清代广东绘画展”21日在澳门艺术博物馆开幕，展出粤港澳三地多家博物馆馆藏清代广东绘画精品。 清代广东绘画是澳门艺术博物馆重要特色馆藏。本次展览以澳门艺术博物馆馆藏为基础，结合广东省博物馆（广州鲁迅纪念馆）、广州艺术博物院（广州美术馆）、香港艺术馆珍藏，共计展出136件（套）书画精品，呈现清代早、中、晚期54位画家在山水、花鸟、人物题材方面的成就，展示清代广东绘画在笔墨技法、题材开拓及中西艺术交融方面的多元探索。 据介绍，清代以前见诸文献及画迹的广东画家有限。清代…"
