    "content": "新华社纽约8月21日电（记者徐静）美国总统特朗普21日表示，美国将在未来90天内允许免关税进口最多30万吨碎牛肉，以降低国内消费价格。 特朗普当日在社交媒体“真实社交”发文说，未来90天内，美国将允许进口最多30万吨的碎牛肉，且不征收配额外关税，“这些牛肉的售价将比当前市场价格低25%”。 特朗普称，这一举措“旨在降低美国民众的消费价格，同时也为美国畜牧养殖业恢复增长提供空间”。 美国消费者长期面临食品价格高企的压力。此外，受伊朗战事引发的能源危机影响，美国的燃料和运输成本持续攀升。据美国媒体报道，物价上涨是特朗普…"
