    "content": "去博物馆把文物“潮玩”带回家，到特色市集体验非遗技艺，在古街巷弄打卡沉浸式夜游……这个暑期，传统文化以创新姿态融入日常生活，文旅市场的蓬勃活力令人瞩目。 文化是旅游的灵魂，旅游是文化的载体。习近平总书记深刻指出：“旅游是修身养性之道，中华民族自古就把旅游和读书结合在一起，崇尚‘读万卷书，行万里路’。” 以文塑旅、以旅彰文，是建设旅游强国的内在要求。 在地方工作时，习近平同志就提出“要把历史文化与现代文明融入旅游经济发展之中”。 《之江新语》中《发展旅游经济要坚持创新与继承相统一》一文这样指出：“加快发展旅游经济，建…"
