    "content": "中国非物质文化遗产馆近日推出“可以观”非遗社教演艺活动，探索构建“观演启蒙、情感共鸣、社群聚合、在地践行”的非遗传承体验新场景路径。 本次演艺活动以四季时序为创作脉络，设置《茶》（春）、《瓷》（夏）、《染》（秋）、《年》（冬）四季篇章，融合诗、书、印、琴、舞、音、歌等多元艺术呈现，巧妙串联起中国剪纸、龙泉青瓷传统烧制技艺等20余项非遗代表性项目，生动展现非遗技艺融入四时生活、浸润烟火人间的鲜活图景。演出以老匠守艺、少年传艺的双线叙事，诠释工匠精神、生活美学与家国情怀。 中国非物质文化遗产馆推出“可以观”非遗社教演艺…"
