    "pub_date": "2026-08-21 21:23:36",
    "author": "",
    "description": "中新网8月21日电 据应急管理部微信公众号消息，北部湾热带低压已于21日下午加强为今年第19号台风(热带风暴级)，预计21日夜间至23日白天，该台风将在北部湾海面回旋少动，强度缓慢加强，最强可达强热带风暴级。受其和西南季风共同影响，未来三天，海南、广西南部、广东沿海地区将有大到暴雨，局地大暴雨。中央气象台8月21日18时发布台风蓝色预警和暴雨蓝色预警。",
    "content": "中新网8月21日电 据应急管理部微信公众号消息，北部湾热带低压已于21日下午加强为今年第19号台风(热带风暴级)，预计21日夜间至23日白天，该台风将在北部湾海面回旋少动，强度缓慢加强，最强可达强热带风暴级。受其和西南季风共同影响，未来三天，海南、广西南部、广东沿海地区将有大到暴雨，局地大暴雨。中央气象台8月21日18时发布台风蓝色预警和暴雨蓝色预警。"
