    "pub_date": "2026-08-21 21:04:46",
    "author": "韩依格,陈旺",
    "description": "贝壳烧灰当粘合剂，花岗岩作主体，屋顶瓦片上还压着一块块石头。这就是福建平潭独特的民居，石头厝。 8月20日，新华社记者跟随“活力中国调研行”采访团来到福建平潭，探寻平潭传统民居的焕新故事。 平潭位于福建省东部，从福州南站出发，高铁37分钟即可抵达，是海岛游的热门目的地。为适应海岛气候，村民们就地取材，用花岗岩建造石厝主体，屋顶以石压瓦，这样建出来的房子不仅可以抵御大风，还能抗海风腐蚀。 8月20日，游客在福建平潭68海里景区的“68航标…",
    "content": "贝壳烧灰当粘合剂，花岗岩作主体，屋顶瓦片上还压着一块块石头。这就是福建平潭独特的民居，石头厝。 8月20日，新华社记者跟随“活力中国调研行”采访团来到福建平潭，探寻平潭传统民居的焕新故事。 平潭位于福建省东部，从福州南站出发，高铁37分钟即可抵达，是海岛游的热门目的地。为适应海岛气候，村民们就地取材，用花岗岩建造石厝主体，屋顶以石压瓦，这样建出来的房子不仅可以抵御大风，还能抗海风腐蚀。 8月20日，游客在福建平潭68海里景区的“68航标塔”附近游玩。新华社记者 杜潇逸 摄 近年来，平潭编制了《石头厝保护专项规划》，…"
