    "content": "新华社太原8月21日电 山西省纪委监委21日发布消息，日前，经山西省委批准，山西省纪委监委对山西省投资促进局原党组书记、局长杨春权严重违纪违法问题进行了立案审查调查。 经查，杨春权丧失理想信念，漠视党纪国法，无视中央八项规定精神，收受礼品、礼金；违背组织原则，不按规定报告个人有关事项，在职务调整中为他人谋取利益并收受财物；不正确履行职责，致使民生工程长期停滞，干预和插手工程项目；利用职务便利，为他人在企业经营等方面谋利，并非法收受巨额财物。 杨春权严重违反党的组织纪律、廉洁纪律和工作纪律，构成严重职务违法并涉嫌受贿…"
