    "pub_date": "2026-08-21 20:57:54",
    "author": "李怡汐,张申博",
    "description": "谁是剪花娘子？她是谁，有怎样的人生经历，又为何被联合国教科文组织授予“民间工艺美术大师”的称号？ 记者前往陕西咸阳旬邑县，探访库淑兰故居与旬邑县非遗陈列馆，感受植根黄土地的传统手艺，在一代代传承者手中薪火绵延的蓬勃生机。 记者：李怡汐、张申博 摄像：郑长庚 鸣谢：旬邑县文化馆、旬邑县非物质文化遗产陈列馆、旬邑县融媒体中心 新华社音视频部制作",
    "content": "谁是剪花娘子？她是谁，有怎样的人生经历，又为何被联合国教科文组织授予“民间工艺美术大师”的称号？ 记者前往陕西咸阳旬邑县，探访库淑兰故居与旬邑县非遗陈列馆，感受植根黄土地的传统手艺，在一代代传承者手中薪火绵延的蓬勃生机。 记者：李怡汐、张申博 摄像：郑长庚 鸣谢：旬邑县文化馆、旬邑县非物质文化遗产陈列馆、旬邑县融媒体中心 新华社音视频部制作"
